INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1088172-ce203', 'stk-mr.cool', 'CE 203', 'info', '{"desc": "هذا الكورس يعتمد على CE201 إعتماد تقربيا كلي …\n\nيتم فيه تطبيق نفس المعادلات و طرق الرسم و التحليل و لكن لدراسة الstress .\nو فيه زيادة في المعادلات و دراسة خصائص المواد المصنوع منها الجسم و هكذا …\n\nو في النهاية أسئلة المياجر نفس طريقة أسئلة CE 201", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/4", "user": "Mr.Cool", "ts": 1346986914000, "tid": 120668, "pn": 4}}', 1346986914000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1125273-ce203', 'stk-user6430', 'CE 203', 'info', '{"desc": "هذا تقيم لكتاب المادة\nالكتاب مفيد و حقيقة كتب المؤالف كلها تصلح أنها تكون دراسة بنفسك ( self-study )\nالمشكلة أنا المياجر تأتي فوق مستوى الشرح الذي تلاقاه الطلاب فليس كل الطلاب عند نفس المدرس\nو المدرسين بعضهم يعتبر أنه على كل طالب يجي لازم يكون محضر و هذا الذي يجب أن يفعله الطالب الجامعي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/7", "user": "user6430", "ts": 1354033513000, "tid": 120668, "pn": 7}}', 1354033513000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1164887-ce203', 'stk-abu_hamad', 'CE 203', 'info', '{"desc": "طبعاً الكورس الكثير من الطلاب بيشتكي منه …بس اذا اخذته عن دكتور كويس (الخثلان هو افضل من يدرس الكورس ) الكورس بيكون سهل وممتع …مثلا انا كنت عند الدكتور الخثلان وكان شرحه والهانداوتس اللي يعطيناها كافيه وما احتاج ارجع الى الشرح اللي في الكتاب لفهم الكونسبت …\n\nاذا تبقى درجه كويسه في الكورس فماعليك الا : 1) تحاول قدر الامكان تسجل عن دكتور كويس افضلهم هو الخثلاث بعده الصويان وبعدهم الدليجان\n2) تنتبه مع الدكتور وتكتب نوت معاه وتجمع الهانداوتس اللي يعطيك اياها الدكتور وتذاكرهم قبل لاتبدأ في الهومورك\n3)حل اسئلة الهومورك…والامثله اللي في الكتاب وتكون مشابه للهومورك(( افكار المياجر والفاينل ماتخرج عنها بس يبقى لك تحلها اكثر من مره عشان تثبت الفكره وتكون سريع في الحل ))", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/9", "user": "Abu_Hamad", "ts": 1358325629000, "tid": 120668, "pn": 9}}', 1358325629000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1164994-ce203', 'stk-user6686', 'CE 203', 'info', '{"desc": "المادة حليوة وبه افكار واااجد ومهمة جدًا سواء للـ ce او الـ me\n\nاخت الـ 201 الكبيرة باختصار 🙂\nمع بعض الاضافات … وطبعا اصعب وبمراحل\n\nفهم الهومووركات اهم شي لانه هي الزبدة وتقريبا شاملة كل الافكال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/11", "user": "user6686", "ts": 1358345172000, "tid": 120668, "pn": 11}}', 1358345172000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1251062-ce203', 'stk-s2010xxxxx', 'CE 203', 'info', '{"desc": "كورس جميل وممتع. ويفضل يكون دكتورك كويس بالماده عشان تسهل عليك… الماده هذي اعتبرها سهله من ناحيه الكونسبت. لكن مشكلتها انهم يمديهم يجيبون لك اسئله مستحيل تحلها. هالماده تعتمد على صعوبه الاسلئلة بالترم نفسه. وركز على اسئلة الهوموورك لانها مهمه جدا. انا انصح انك تنزلها بالصيف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/12", "user": "s2010xxxxx", "ts": 1375446654000, "tid": 120668, "pn": 12}}', 1375446654000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381740-ce203', 'stk-abo_ali', 'CE 203', 'info', '{"desc": "مادة جدن مهمه لأي مهندس , تعطيك تخيل واسع عن اللي صاير حولك\n\n--------------\nجودة المقرر بشكل عام\nممتاز جدن , ماغير آخر جزء فيه كان شوي ملحوس 😦\n\nالمواضيع التي يغطيها المقرر\nما اذكر , لكن هو زبدة الكورس , مجموع القوى يساوي صفر 🙂\n\nالكتاب المستخدم للمقرر\nمناسب جدن , واهم شيء الفندمنتل بروبلمز ,\n\nالأسئلة والأمثلة المستخدمة في المقرر\nمناسب جدن جدن , وكافية جدن 🙂\n\nمدى فائدته في الناحية التطبيقية\nراح يعطيك تصور اوسع من اللي كسبته في 201 لب قلبها 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/14", "user": "Abo_Ali", "ts": 1403436061000, "tid": 120668, "pn": 14}}', 1403436061000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437757-ce203', 'stk-dyaa94', 'CE 203', 'info', '{"desc": "خذتها في 151\n\nالكورس من بعد ميجر 1 يبدأ يسهل…ميجر 2 والفاينل كانو عندي اسهل من ميجر 1\n\nالماده يبغالها شوي جيومتري وتدريب ع المسائل خاصة لميجر 1…ركزززززز ع ميجر 1\n\nشي ماعجبني…المياجر اربع اسئله كل سؤال يكتبه دكتور ويصححه بعدين…والدكاتره كانو جدا شديدين ب التصحيح\n\nبس overall ماده تعتبر متوسطة الصعوبة عندي احسن واحلى من CE201… + القرديدنق شوي عالي يعني السي بلس +70\n\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/16", "user": "Dyaa94", "ts": 1451737104000, "tid": 120668, "pn": 16}}', 1451737104000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467145-ce203', 'stk-m_faddagh', 'CE 203', 'info', '{"desc": "اخذتها في 153 مع الاسطى\nالمادة كان يدرسها الاسطى وشمشاد\n\nللأمانة المادة جدا جدا سهلة خاصة الجزء الاخير منها ، فقط مشكلتها طول الحل في بعض المسايل\nكانت اسهل من CE201 بسبب التعقيد في CE201 اللي حطوه من بعد ترم 151 الله يهديهم\n\nانا اخذتها صيف مع ME201 و اسلامي وطلعت ب A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/20", "user": "m_faddagh", "ts": 1485597812000, "tid": 120668, "pn": 20}}', 1485597812000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1473977-ce203', 'stk-user10533', 'CE 203', 'info', '{"desc": "أخذتها فـ 162\nالمادة سهلة مقارنةً بـ CE 201 والديبارتمنت المخيس حقهم 😞\nماتحتاج حل طويل بقدر ما تحتاج فهم ! فيها قوانين واجد لكن اذا فهمت بس يسهل عليك كل شي\nتحتاج متابعة لأن المواضيع مترابطة…\nالميجر الأول كنت اشوفه صعب , الميجر الثاني سهل , الفاينل ما أقدر أحدد لأني ما ذاكرت زين بسس الضغوطات اللي صارت 😕\nباختصار نزلها عند الخثلان او الصويان وبيسهل عليك كلش …\n\nوشكراً ❤️ ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/21", "user": "user10533", "ts": 1495985817000, "tid": 120668, "pn": 21}}', 1495985817000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1521727-ce203', 'stk-abofordan2004', 'CE 203', 'info', '{"desc": "TERM 192\nالمادة اخذتها عند الدكتور افريقي وبكل صراحة كانت صدمه مقارنة ب CE201 من ناحية المواضيع والقوانين بحيث ان 201 من سهولتها وقلة قوانينها تعتبر مادة قريد\nالمادة ذي فيها قوانين كثير وصدقني لما اقولك كثيييييير كبداية صراحه اول مواضيع كانت واضحة وسهل فهمها ونوعا ما ممتعه في الحل لكن بعد الميجر الاول بكم درس تبدا تتعقد الامور وتكثر القوانين اكثر واكثر\n\nف نصيحتي لك خل عندك زي الملزمة او الدفتر واكتب فيها كل القوانين لانها بتسهل عليك المذاكره والحل , ومن ناحية الاساله حاول تحل من سلايدات الديبارتمنت (الظاهر نفسها عند كل الدكاترة) لان بعضها يجيك بالكويز او الميجر نسخ لصق بس يغيرون الارقام\n\nوانصح بشكل كبير متابعة الدكتور الامريكي jeff hanson شرح واضح وممتاز صدقني بينقذك ويسهل عليك كثير في ذا المادة وهذا رابط قناته باليوتيوب :\n\nOnline Solids Course - YouTube\n\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-structural-mechanics-i/120668/23", "user": "AboFordan2004", "ts": 1588503504000, "tid": 120668, "pn": 23}}', 1588503504000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p243696-ce203', 'stk-user1491', 'CE 203', 'info', '{"desc": "السلام عليكم و رحمة الله و بركاته …\n\nكيف الحال شباب ان شاء الله طيبين …\n\nحبيت اسأل عن الدكتور الخثلان … كيفه من ناحية التعامل القريد الشرح الخ … و هل يستحق اني اضحي بالدكتور فيرق لماث 202 علشانه لأنه مناسب لجدول الفاينلات احسن من الماث … و المادتين مهمات ابي ارائكم 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/61419/1", "user": "user1491", "ts": 1202881975000, "tid": 61419, "pn": 1}}', 1202881975000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p269131-ce203', 'stk-user2730', 'CE 203', 'info', '{"desc": "الخثلان ممتاز جدا من حيث:\n1) الأخلاق والتعامل مع الطلاب.\n2) الشرح وتفهيم المادة بوضوح.\n3) يعطيك نوت ممتاز جدا.\nطبعاً… الدكتور نظامي جدا يعني تأخير مافيه، ويكرفك في الهوموركات\n-------------------\nالصويان من ناحية الأخلاق والشرح فمن أفضل الدكاترة في الهندسة المدنية، لكن احلم بقريد وتتعب عشان تاخذ معاه نوت…\n------------------\nوبالمناسبة المادة دسمة جدا… ويبغالك تشد حيلك\n\nبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/61419/23", "user": "user2730", "ts": 1211721397000, "tid": 61419, "pn": 23}}', 1211721397000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p269888-ce203', 'stk-_legend', 'CE 203', 'info', '{"desc": "شرحه ممتاز يعطيك الكونسبت و يحل لك امثلة من النوت حقه , و النوت يعطيه الطلاب كل اسبوعين المتيريال الجديد …\nهومووركاته اسبوعية , كل سبت لااااااااااااازم تسلم , ما في تأخير هوموورك مقبول\nالمياجر طويلة و صعبة \" بالنسبة لي \" , الافرج بالميجر1 73% الميجر 2 65%\n\nالقريدنج عنده افرج , لكن لما يكون الافرج عالي يتحول لستاندرد …\nكوزاته سهلة , و كل اسبوعين كوز رسمياً !\n\nانصح به … الشايع لا تفكر فيه !", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/61419/33", "user": "_legend", "ts": 1211961221000, "tid": 61419, "pn": 33}}', 1211961221000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p693476-ce203', 'stk-banyan', 'CE 203', 'info', '{"desc": "الخثلآن هو الأفضل من دووون منازع وبمرتبة الشرف الاولى مع اني ما اخذت كورسات مع الصويان\nشررح قمممممة… بل أعلى من القمة\nيكفيك من الشرح النوت اللي يكتبه على السبورة… اذا تفهمه صح a+ تاخذها وانت مرتااح\nالكورس كومن + الهوموركات كومن زكلشي كومن\nيحضر اول خمس دقايق يهتم جدا للتحضير\nكلاصه متعة\nهذا كله رأيي الشخصي يمكن تتفق معاي ويمكن لآ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/94153/4", "user": "Banyan", "ts": 1283136236000, "tid": 94153, "pn": 4}}', 1283136236000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p854083-ce203', 'stk-eng.ammar', 'CE 203', 'info', '{"desc": "تقريبا نفس طريقة الـ 215 لكن أتقل منها بكثير لأنه فيها كمية معلومات خرافية\nالمادة سهلة للي يذاكر اول بأول أو بالأصح اللي يحفظ أول بأول\nلو تبغا تجيب فيها جريد حلو فيها سوي التالي\n1 - لا تغيب ولا كلاس مهما كان السبب لأنه صعب جدا تفهم من الكتاب اللي فاتك لوحدك\n2- حل الهومورك و أفهمه لأنه 100 % المسائل في الاختبارات نسخة منه إلا مسألة وحدة جديدة و في الغالب محد يحلها صح\n3- أقرأ الكتاب أقرأ الكتاب أقرأ الكتاب أقرأ الكتاب أقرأ الكتاب أقرأ الكتاب أوووووووول بأوووووووول\nاللاب على حسب الدكتور بس ما ياخد أكتر من ساعة و نص او ساعتين بالكتير و ركز عليه لأنه عليه 20 % من الفاينل جريد\nأغلب الطلاب يكره المادة و يقول إنها صعبة بسبب حفظها بس شد حيلك و صدقني لو تذاكر الكتاب حتجيب جريد\nموووفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-me-206/108474/2", "user": "Eng.Ammar", "ts": 1308176419000, "tid": 108474, "pn": 2}}', 1308176419000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1412642-ce203', 'stk-a_dulaziz', 'CE 203', 'info', '{"desc": "ما اعرف كيف وضع القريدات\n\nلاكن الشرح عندك الي بينزلونها السمستر الجاي\n\nالخثلان و الصويان\n\nكلهم توب\n\nانا جربت الخثلان فقط و اشوف انه الأفضل بالقسم لاكنه شديد\n\nشديد بالهومورك (يعطي هاند اوت ما في سلوشن) و التحضير بالدقيقة ويومي\n\nلاكن شرحه روعه الكلاس كله يخش جو معاه نادر تحصل واحد مسرح\n\nو الدكتور مرتب جدا تقدر تكتب نوت معاه بسهولة\n\nما قد جربت الصويان لاكن كثير يمدحونه و الي درسهم عندهم اثنينهم يرجح كفة الخثلان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce203/167254/4", "user": "A_DULAZIZ", "ts": 1416088877000, "tid": 167254, "pn": 4}}', 1416088877000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1377138-ce203', 'stk-s_h_a_d_o_w', 'CE 203', 'info', '{"desc": "ُُEE 204\nمذاكرة الكتاب والأمثلة ثم حل الواجب\n\nCE203\nمذاكرة سلايدات شمشاد أحمد وفهم الأمثلة والتدرب على حلها وحل الواجب…\nالسلايدات سبق ورفعتها على kfupmresources\nلكن الظاهر ان الموقع غير متاح حاليا فرفعتها على الدروب بوكس\nhttps://www.dropbox.com/s/ou4zoo4gr5s0pha/CE203-Shamshad-Slides.rar", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee204-ce203/162266/3", "user": "S_H_A_D_O_W", "ts": 1401894751000, "tid": 162266, "pn": 3}}', 1401894751000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1379899-ce203', 'stk-a7madd', 'CE 203', 'info', '{"desc": "الـEE204 الكتاب جميل جداً اذا عندك وقت. بس انتبه للأشياء اللي مو داخلة معكم في الكورس (مثل الـtime-dependant voltage/current sources) عشان تتجنبها.\nأما إذا مزنوق وتبي شيء سريع فأنصحك بالـElectronic Lectures تلقاها في الويب سي تي الأونلاين.\n\nالـCE203 ما اقدر اعطيك نصيحة معينة لأنها تختلف من شخص لآخر، ناس يحبون يحلون الـFundamental problems ويفهمونها وناس يذاكرون الهومورك وناس يفهمون من الدكتور و و و …الخ. شف أكثر طريقة تنفع معك.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee204-ce203/162266/7", "user": "A7madd", "ts": 1402758255000, "tid": 162266, "pn": 7}}', 1402758255000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1163522-ce203', 'stk-eng.alwaleed', 'CE 203', 'info', '{"desc": "السلام عليكم …\n\nمبروك للجميع نهاية الترم الدراسي الطويل عساه يكون ترم خير للجميع …\n\nيمكن يكون العنوان شديد اللهجة ، ولكن ما في الصدور اكثر واكثر من هالكلام …\n\nاتمنى ما يجيني احد مشوت ويحسبني اتكلم على الجامعة أو طريقتها ( خصوصا اني احبها ❤️ ) …\n\nولكن الموضوع ببساطة عن مادة ce 203\n\nانا اتكلم عن نفسي وكم شخص اعرفه وليس عن جميع الطلاب طبعا …\n\nمجموعي قبل الاختبار النهائي 55 من 65 والافرج كان 38 تقريبا ، وطلعت من الفاينل راضي تمام الرضى عن مجهودي ومتأكد اني فوق ال 25 من 35 في اسوء الاحوال … كيف يكون القريد النهائي b !!!!!!!\n\nاتمنى من اللي عنده اي افادة ما يقصر معنا …\n\nوعذرا عالاطالة 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/138317/1", "user": "Eng.alwaleed", "ts": 1358084556000, "tid": 138317, "pn": 1}}', 1358084556000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1163532-ce203', 'stk-metallic', 'CE 203', 'info', '{"desc": "وعليكم السلام ،\n\nلا يضيق صدرك من هالديبارتمنت اللي ما عمري قد شفت أحد راضي عن توزيع القريدات فيه !\n\nمواساتي لك هي أنك بتبدع بإذن الله بكورس 307 me لأنه يعتمد اعتماد كلي على هالكورس لدرجة أن متيريل ميجر ون ما طلع من متيريل السي اي ! يعني ولا كأنك تعلمت شيء جديد !\n\nالله يعوضك خير ، وبإذن الله أن تعبها ما ضاع عليك وبتحصله بعدين … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/138317/2", "user": "METALLIC", "ts": 1358085234000, "tid": 138317, "pn": 2}}', 1358085234000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1036933-ce203', 'stk-user4636', 'CE 203', 'info', '{"desc": "السلام عليكم\n\nانا ياجماعه باختصار انضغطت بالفاينلات وماعندي وقت اذاكر لهالماده\n\nعندي الخميس اي اي 204 والسبت ماث 301 بالليل والسي اي عندي الاثنين الساعه 7 الصبح!!\n\nماعندي وقت الا الاحد اذاكر لها بس وانا مابعد فتحت شي بماتيريل الفاينل\n\nاذكر ايام سي اي 201 كان المنديل الله يذكره بالخير يعطي طلابه نوت ويجي نففففففسه بالفاينل\n\nلولا الله ثم هو كان خذت اف بذاك الكورس بس طلعت بالسبعينات وارتفعت من اف الى دي بلص\n\nالزبده مافيه دكتور يعطي اسئله زي كذا !! 😦\n\nياليت ياشباب اللي دكتورهم عطاهم شي مهم يفيدنا تراني مالي الا يوم واحد بس للمذاكره وأبغا الزبده\n\nابي اذاكر شي ينجحني لأن مجموعي مب ذاك الزود 😞", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/125546/1", "user": "user4636", "ts": 1336924162000, "tid": 125546, "pn": 1}}', 1336924162000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1037129-ce203', 'stk-vip_master', 'CE 203', 'info', '{"desc": "عندي الخميس اي اي 204 والسبت ماث 301 بالليل والسي اي عندي الاثنين الساعه 7 الصبح!!\n\nاذا النوت حقك تمام و تكت مع الدكتور ليت تسعفنا به\n\nال 203\nآخر شابتر انتبه منه بسيط لكن طويل دبر لك اي احد يفهمك هو لا تعتمد على نفسك فيه\nالمور سيركل هذا مية بالمية سؤال جاي عليه\nسهل و بسيط لكن لا تدرسه بنفسك\nاخذ مني ساعتين ايامها بدون ما افهمه و اتصلت على واحد من الشباب في عشر دقايق انتهى امره\nالباقي تقدر تعتمد على نفسك فيه\nيعني شوف احد يفكك من آخر شبترين في نص ساعه بس و الباقي اعتمد على نفسك به", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/125546/4", "user": "VIP_Master", "ts": 1336939531000, "tid": 125546, "pn": 4}}', 1336939531000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1451539-ce203', 'stk-user8890', 'CE 203', 'info', '{"desc": "بالنسبة للنوتات انصحك بالكتاب جدا جيد, وعندك قناة باليوتيوب اسمها StructureFree …\nالمادة فيها أفكار ف انصحك بعد ما تفهم الكونسبت تتدرب… عندك اولد اقزامز وبرضه الهوم ووركات القديمة. هوم ووركات د.شمشاد فيها افكار حلوه.\n\nالمادة اشوفها مغايرة عن الـ 201 ، لكن اكيد بتحتاج الـ 201 عشان تجيب الـ Reactions، بتدرس برضه طريقة رسم الـ Shear Bending Moment Diagram بطريقة اسهل عن من الطريقة الطويلة اللي اخذتها بـ 201.\n\nبوجهة نظري المادة أسهل وأمتع من 201 وفيها واجبات أسبوعية لكن ما ادري عن نظامها بالصيف.\n\nتفضل الملف هذا ان شاءالله بيفيدك بخصوص مصادر للمادة:\n\nDropbox - CE 203", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/173560/4", "user": "user8890", "ts": 1465705673000, "tid": 173560, "pn": 4}}', 1465705673000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1423514-ce203', 'stk-the_aviator', 'CE 203', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته …\nأنا ماخذ المادة معك الآن في الصيف.\nمستحيل تاخذ f ، احسب درجاتك ، ميجر 1 ( 70% = 17.5 ) ، ميجر 2 ( 67% = 16.75 )\nافرض الكوزات جبت فيها 3 من 5 ، والهوموركات 5 من 5 ، ولا تنسى الحضور عليه 5% .\nكذا يصير مجموعك قبل الفاينل تقريبا 45 ، والفاينل عليه كم 35% ؟؟؟؟\nيعني لو تجيب فيه 70 ، يصير مجموعك في الكورس 70 … هذي كم تعطيك c+ أو b ؟؟؟؟؟؟\nفلا تخلي الشيطان يوسوس فيك .\nكل اللي عليك الحين : تحل الهوموركات بعد ميجر 2 وتفهمها ، وتحل الأمثلة في السلايدات الي يشرحها في الكلاس وتفهمها .\nوادخل الفاينل وانت مرتاح\nموفّق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/169189/3", "user": "THE_AVIATOR", "ts": 1439021500000, "tid": 169189, "pn": 3}}', 1439021500000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p99028-ce203', 'stk-user515', 'CE 203', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nتعتبر مادة CE 203\n\nمن المواد الأساسية في الهندسة المدنية\n\nوهذه نصيحة لكل من يريد أن يأخذ هذه المادة أقول له\n\nلا يكن همك فقط الحصول على الدرجة و التقدير\n\nبل يجب أيضاً الحرص على فهم المادة وإستيعابها\n\nوإلا فإنك في المستقبل سوف تعاني من ذلك لأن هناك مواد تعتمد على هذه المادة\n\n…\n\nوبالنسبة لسؤال العضو / الحب المستحيل\nعن مدرسي المادة\n\nفذلك يعتمد على ماذا تريد أنت\nهل تريد دكتور تحصل معه على درجة طيبة ولكن لا تفهم المادة\n\nأم تريد دكتور يساعدك على فهم المادة وإستيعابها جيداً\n\nطبعاً أولاً وأخيراً أنت بمجهودك المبذول تحدد التقدير الذي ستحصل عليه\n\nويجب التنبه أيضاً للتخصص الدقيق لأستاذ المادة الذي يقوم بتدريسها\nهل هو ( هندسة إنشاءات أو هندسة تربة أو هندسة مياه أو هندسة بيئية)\n…\n\nلقد أخذت هذه المادة مع الدكتور / محمد بلوش قبل أكثر من ثمان سنوات\nوطبعاً البرفسور / بلوش من أقدم الدكاترة بالقسم\n\nكان شرحه جيد\nوالحق يقال أن الدكتور /بلوش\nرجل منصف لا يظلم أحد\n\nوبالنسبة لإسلوب الدكتور في تقييم الطلاب\nفإنه يعتمد في تقييمه على عدة أمور وهي:\n1- الحضور و المشاركة معه في الفصل. ( فهو يكره الغياب و الدخول بعده للفصل)\n2- حل الواجبات Homework ( يكره الغش ).\n3- الإختبارات الأسبوعية Quiz ( الدكتور يتابع آداء الطالب في الإختبارات وهذه أهم ميزه فإذا كان مستوى الطالب في تحسن مستمر وملحوظ إنعكس ذلك على درجته الكليه في المادة)\n4- الإختبار الفصلي و النهائي. ( وكما ذكرت فإن الدكتور لا يكتفي بالدرجة فقط بل يتابع مستوى الطالب هل هو في تقدم وإرتفاع أم أنه متذبذب )\n\nإختبارات الدكتور بصفه عامة على مستوى شرحه وهي تقيس مدى إستيعاب الطالب للمادة\n\nهذا ما لدي … وللجميع تحياااتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203-061/50323/9", "user": "user515", "ts": 1148678098000, "tid": 50323, "pn": 9}}', 1148678098000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1052294-ce203', 'stk-_004', 'CE 203', 'info', '{"desc": "الـ Ce 203 لو تب تاخذها عبر وتمشية حال أنصحك لا تنزلها لإن قدامك كورس الـ Me 307 تعتمد بشكل كبير وبشكل ما تتخيله عليها .\nالـ Math 301 ماتيريال ميجر 1 + ماتيريال ميجر 2 وش زينهن حليلات … أما حق الفاينل أعوذ بالله من غضب الله . حاجه غريبة عجيبة نظامنا كان احفظ وامش وعلى الله\nأنا أشوف تنزلهن الثنتين مالهن داعي وش أنت عجل عليه … خذ لك وحده وأنصح بالماث وافتك منها بالصيف\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-301-ce203/127083/4", "user": "_004", "ts": 1339058251000, "tid": 127083, "pn": 4}}', 1339058251000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1350692-ce203', 'stk-abo_yazeed6', 'CE 203', 'info', '{"desc": "الاختبار الأول كان صعب وكثير خبصوا لدرجة أنه المدرسين قاموا يدفون الطلاب على أي خطوة يكتبونها في الاختبار حتى لو كانت خطأ.\n\nعموما حسب معلوماتي القسم هذا غامض وطريقة توزيع القريدات فيه على حسب الأفرج غير معلومة.\n\nخله يشد حيله في ميجر 2 لأنه حسب ما أسمع من الطلاب أنه عادة يكون أسهل والله أعلم.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/159643/2", "user": "abo_yazeed6", "ts": 1397147040000, "tid": 159643, "pn": 2}}', 1397147040000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1303463-ce203', 'stk-user5944', 'CE 203', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته …\nوعليكم السلام ورحمة الله وبركاته\n\nاخواني حبيت استفسر …\nوش وضع هالمادتين في الصيف ؟\nوكيف درجتهم من ناحية الصعوبه .؟\nCE203 متوسطة الصعوبة يعني تقدر عليها بالصيف\nأما 204 مادة سهلة (حرام تنزلها بالصيف)\n\nوهل فيهم ضغوط او لآ ؟\nإذا مشيت معها أول بأول ماكوا صعوبة تذكر\n\nوهل المواد سكشن افرج ؟\nBoth of them …Over all\n\nوكيف المياجر ؟ والهوموركات ؟\nCE203 الدكتور يجيبهم من عنده من خارج الكتاب (هذا ماكان في وقتي)\nEE204 من الكتاب وبطبيعة الكتاب الفاينل أنسر يكون موجود\n\nخصوصا ان الصيف الجاي لك عليه ؟\nنصيحة مني: نزل CE203 بالصيف عشان تفتك من غثاها و EE204 مقدور عليها في السمستر\n\nموفق لكل خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee204-ce203-in-133/153717/2", "user": "user5944", "ts": 1386673824000, "tid": 153717, "pn": 2}}', 1386673824000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1303467-ce203', 'stk-user8551', 'CE 203', 'info', '{"desc": "ما قصر | ميكانيكي ]| بالأجوبة ، و أتفق معه إنك تخلي الـ EE بترم عادي لأنها مادة خفيفة و ممتعة.\n\nنصيحتي : إذا ما خلصت الإنجلش 214 خذه بالصيف مع السي إي ، خصوصا إن إجازة العيد بتفيدك بالإنجلش (تمخمخ عالريبورت 🤠) ، إضافة إلى إن قريدات الإنجلش بالصيف أعلى نوعا ما من الترم العادي.\n\n* تصحيح : هومووركات الـ EE تعتمد عالدكتور ، الدكتور اللي أدرس عنده الحين يجيب لنا هومووركات من خارج الكتاب و صعبة بالحيل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee204-ce203-in-133/153717/3", "user": "user8551", "ts": 1386674528000, "tid": 153717, "pn": 3}}', 1386674528000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p936420-ce203', 'stk-user4394', 'CE 203', 'srcP', '{"html": "السلام عليكم ورحمه الله وبركاته<br><br>ياشباب احد يعرف كيف اجيب التورك في هذا السؤال ؟؟؟؟<br><br>وفي السؤال الثاني ايش يقصد بالضبط؟؟؟<br><br>بسرعه لو سمحتور<br><br>الملف في المرفقات<br><br>​<span data-fid=\"stk-f936420-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f936420-0": {"name": "RelativeResourceManager.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/quiz-4-ce-203-help/115526/1", "user": "user4394", "ts": 1322150979000, "tid": 115526, "pn": 1}}', 1322150979000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1149190-ce203', 'stk-user6282', 'CE 203', 'srcP', '{"html": "…<br><br>…<br><br>السلام عليكم<br><br>الدكتور عطانا كويز تيك هوم وعلى مايبدو انه نفس السمسترات الماضية …<br>فياريت اذا احد يقدر يساعدنا بالحلول …<br><br>الكويز بالمرفقات …<br><br>تحياتي<br><br>​<span data-fid=\"stk-f1149190-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1149190-0": {"name": "Quizzes_05 and 06.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ce-203/137053/1", "user": "user6282", "ts": 1356671129000, "tid": 137053, "pn": 1}}', 1356671129000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammad.as-ce203', 'stk-mohammad.as', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98555", "n": "Dr. Salah U. Al-Dulaijan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 103\n\nce203\n\nالتحضير : يومي احيان بداية الكلاس واحيان نهايته لو حضر ببدايته وماتأخرت كثير تقدر تقوله يحضرك نهايته\n\nطريقة الشرح : يشرح اول عشر دقايق الكونسيبت بعدين يبدا يحل امثله كامله بعضها من عنده يعني اولد اقزامز وكذا وبعضها من اسئله الكتاب شررحه رائع ومرتب ومفهوم\n\nالكويزات : من اسئلة الهومورك\n\nالمياجر: من اسئلة الهومورك او اللي يحلها بالكلاس\n\nالفاينلات :من اسئلة الهومورك او اللي يحلها بالكلاس\n\nالقريد النهائي: A++++++++\n\nالصوت: واضح\nإضافات : الدكتور رائع من اروع مايكون تعامل واخلاق وشرح ويعطي هنت للمياجر رهيييب مره من افضل الدكاتره اللي درست عندهم …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p889521-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-salah-u-al-dulaijan/98555/5", "user": "mohammad.as", "ts": 1313944194000, "tid": 98555, "pn": 5}}]}', 1313944194000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.cool-ce203', 'stk-mr.cool', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98555", "n": "Dr. Salah U. Al-Dulaijan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce203 - 112\n\nالتحضير :\nيوميا بآخر الكلاس و بعض الأحيان في أول الكلاس و المتأخرين يحضرهم في الآخر .\n\nطريقة الشرح :\nشرحه ممتاز للغاية و يهيئك للمياجر بطريقة ممتازة .\nيستعمل السلايدات للكونسبت و الرسومات.\n\nالكويزات :\nسهله جدا …\n\nالمياجر:\nكومن\nالفاينلات :\nكومن\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح و اللغة ممتازة .\n\nإضافات :\n\nهذا الدكتور من أفضل من درست عنده إذا ما هو الأفضل …\nأخلاق و شرح و مساعد في الدرجات و كل شيء …\nو يميزه كثرة الأوفيس أورز …\n\nباختصار إذا وجد له سكشن مفتوح نزل على طووووول !!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047820-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-salah-u-al-dulaijan/98555/11", "user": "Mr.Cool", "ts": 1338349621000, "tid": 98555, "pn": 11}}]}', 1338349621000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6686-ce203', 'stk-user6686', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98555", "n": "Dr. Salah U. Al-Dulaijan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203\n121\n\nالتحضير :\n\nيوميا آخر الكلاس ولا يحاسب على التاخير\nعقب اسبوعين يحفظ الطلاب ويبدا يحضر بالنظر\n\nطريقة الشرح :\n\nشرحه ممتاز للغاية و يهيئك للمياجر بطريقة ممتازة\nيستعمل السلايدات للكونسبت و الرسومات اول 10 دقايق\nباقي المحاضرة كله حل اولد اقزام\n\nالكويزات :\n\n5 كويزات كوبي بيست من الهوموورك\n\nالمياجر والفاينلات :\n\nكومن\n\nالقريد النهائي: A+\n\nالصوت: واضح\n\nإضافات :\n\nوالله هالآدمي اني احبه في الله … شرح, اخلاق , قريد … جامعٍ الزين كلّه\n\nيقول الميكانيكال يبونه يدرّس عندهم … ان شاء الله يوافق ❤️\n\nانت جربتهم كلهم ؟", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164966-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-salah-u-al-dulaijan/98555/13", "user": "user6686", "ts": 1358341815000, "tid": 98555, "pn": 13}}]}', 1358341815000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-harry_potter-ce203', 'stk-harry_potter', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - 102\nالتحضير: حضر اول يوم وحفظ اسامي الطلاب كلهم ما شاء الله عليه وبدا يحضر كل يوم على المزاج مره اول الكلاس ومره بالاخير بدون ما يذكر الاسامي 🤠\nحط عليه 5 درجات من الكلاس ورك 15 درجه\nالشرح: فنان في الشرح ما شاء الله عليه يعطيك فكره سريعه عن الموضوع بعدين ينتقل من سؤال الى سؤال 🤴\n\nالصوت: 10/10\n\nالكوزات: عطانا 4 واخذها كلها وحط عليها 5 درجات من 15 الكلاس ورك\n\nالمياجر و الفاينل: كومن\n\nالهوم وركات: كومن وحط عليها 5 درجات\n\nاضافات: دكتور رهيب بس ركز معاه شوي وذاكر اول بول لااه يناقش المواضيع بالكلاس\n\nالتقييم النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856082-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/13", "user": "harry_potter", "ts": 1308573117000, "tid": 98557, "pn": 13}}]}', 1308573117000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dok116-ce203', 'stk-dok116', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203 ترم 111\n\nمن أفضل الدكاترة اللي درسوني في الجامعة\nالدكتور شرحه رااااااااااائع ويغنيك عن قراءة الكتاب العقيم , يفهمك المبادئ الأساسية بشكل رااائع وومتع ويبدأ يحل مسائل , وميزته انو لما يحل المسائل يحل بحرية تامة بدون أي تعقيدات وهذا أفضل شي أشوفه فيه , يعني لما يحل يخليك تفهم مو تحفظ , المادة بتصير سهلة معاه\nيهتم بالتحضير وحاط عليه 5 درجات من الكلاس وورك\nالعشرة الدرجات الباقية نصها هومووركس ونصها كويزات ( ثلاث كويزات )\n\nمن الآخر الدكتور محمد الصويان أتمنى إني أنزل معاه مادة ثانية , دكتور شريح وأخلاق عااااااااااااااالية جداً وتعامل رااااااااقي وممتاز جداً جداً في الأوفيس , حبيت المادة بعد ما أخذتها معاه\n\nالله يوفقه وين ماكان 🌹🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p967757-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/17", "user": "dok116", "ts": 1326573179000, "tid": 98557, "pn": 17}}]}', 1326573179000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-black_light-ce203', 'stk-black_light', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203 term 111\nبصراحة انا كنت متخوف من الـ Ce 203 لأنها تعتمد على الفهم بشكل كبير جداً\nالصويان بكل بساطة اذا ركزت معاه بكل كلاس راح تكون المادة من امتع المواد بغض النظر عن اختباراتها الصعبة\nيريحك من قراءة الكتاب للفهم وهذا شي انا ماكنت اتوقعه راح يصير لي (لأني اعتمد على الكتاب بالفهم دائماً)\nيبسط المادة ويخليك تحترمها لأنه يشرحها وقوانينها بشكل عقلاني ويخليك تفهم بالظبط المتغيرات بالفورملا وليش وضعوها الي كتبو الفورملا\nتعامله راقي ومتواضع بنفس الوقت, لكن هذا مايعني انه متساهل (حقاني, بس يحقله بصراحة لأن شرحه يسوى ذهب)\n\nاذا قدرت تحصل عنده, نزل بدون ماتفكر, حتى لو كان على حساب كورس متعارض\n\nملاحظة: انا مو دافور, بس طلعت من المادة فاهمها عن بكرة ابيها, ومع الصويان قدرت احل اغلب المسائل الي بالكتاب\n\nبالأخير هذا مايعني انك ماتحل مسائل وتعتمد على الشرح فقط, لأنه هو ماراح يمسك يدك ويحل بدالك!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p973541-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/18", "user": "Black_Light", "ts": 1327481780000, "tid": 98557, "pn": 18}}]}', 1327481780000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s2010xxxxx-ce203', 'stk-s2010xxxxx', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce203-term123\nمدرس كويس جدا بالشرح وممكن يكون افضل مدرس بيمر عليك من الناحيه هذي…واخلاقه عاليه جدا ما شاء الله… عنده مشكله بناحية التصحيح. شديد جدا وما يتسامح ابدا…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251060-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/24", "user": "s2010xxxxx", "ts": 1375446448000, "tid": 98557, "pn": 24}}]}', 1375446448000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah-1-ce203', 'stk-abdullah-1', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203---term 151\n\nالتحضير :\nاخر الكلااااس ويحفظ الاسماء من اول اسبووع\n\nطريقة الشرح :\nطرييقة جبااارة يبسط الكونسبت ويبدا من الصفرر… يركز بشكل كبييير جدا على الكونسبت وطريقة التعامل مع السؤال.\n\nالكويزات :\nاختبرنا 2 سهلة جدا\n\nالمياجر: كومون\nالفاينلات : كومون\n\nالقريد النهائي:\n+ِِa بالرااااااااحة\n\nالصوت:\nوااااضحة جداا\n\nإضافات:\n\nالكلاس وورك 15 :\n5 حضوووور ( 3 غيابات فررري)\n5 مشاااركة (هديية للجميع)\n5 كويزات ( 3 هدية للجميع + 1 كويز + 1 كويز)\n\nالدكتووور اخلااااق ويهتم في فهم الطلاب ويتجاااوب مع الاسئلة\nانصصصصح فيييه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437898-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/26", "user": "abdullah-1", "ts": 1451834694000, "tid": 98557, "pn": 26}}]}', 1451834694000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10533-ce203', 'stk-user10533', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - 162\nباختصار الدكتور من أفضل دكاترة القسم ,\nواذا تقدر تنزل نزل عنده وانت مغممض!\nيشرح بذمة وضمير ويوصل المعلومة بشكل خيالي , حتى كان ف كل شابتر يقولك عاللي تركز عليه والاسئلة اللي ممكن تجي …\nتعامله واخلاقه تفتح نفسك للكلاس دائماً مبتسم ماشاء الله عليه , ويجاوب على اسئلة الطلاب حتى لو كانت تافهه او سهلة …\nالكويزات كانت كلها تيك هوم وتقريباً واجباته اسبوعياً , وهذا شيء كويس لأنه مايخليك تسحب عالمادة. 👍\nالتقييم : A+\n\nالله يوفقه ويسعده ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473974-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/27", "user": "user10533", "ts": 1495985388000, "tid": 98557, "pn": 27}}]}', 1495985388000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-ce203', 'stk-user10610', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE203-191\n\nأسطورة الأساطير افضل دكتور مر علي في حياتي.\n\nالصوت : وااااااضح عربي وانجليزي\n\nالشرح : الدكتور بروفيسور، والشرح كوكتيل من كل شي. بحكم خبرته يدخل المعلومة في رأسك بشكل عجيب، يعني يخليك انت تفكر ويجيب كل احتمالات السؤال وبكل طريقة يشرح لك.\n\nالكوزات : الجميع فل، يعني ورقه ويحل لك السؤال على السبورة وانت تنقل وتكتب اسمك بس 😁2:. يعني يكون الكوز جزء من الشرح يعني بس انت تكتب في الورقة.\n\nالتحضير : بالسيريال نمبر للجميع.\n\nالتصحيح : كل دكتور في الديبارتمنيت يحط سؤال ويصححه، لذلك ما بيصحح لك اي شي.\n\nإضافات : اذا انت فنان وكذا بيعرف اسمك ويناديك باسمك طوال الترم وكذا ويحرص عليك أكثر انك تفهم وتشارك، وإذا انت من حالك في شانك تجلس ورا على جوالك أيضا ما بيقول لك شي ولا يسأل ويحشرك ولا شي. يعني جيد في كل الحالات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518711-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/28", "user": "user10610", "ts": 1578146840000, "tid": 98557, "pn": 28}}]}', 1578146840000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ce203', 'stk-guest', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - term 182\n\nالتحضير :\nبشكل يومي\n\nطريقة الشرح :\nيكون محضر سؤال سؤالين للدرس يغطي المفاهيم بصورة واضحة و انت تكتب وراه بعدها يحط السؤال بدون حل و مافي سلايدات. كان شرحه غير مرتب يرسم على اليمين و يروح يسار و فجأة يمين لكن مع التركيز يفهمك الكونسبت.\n\nالكويزات :\nسهلة جدا مع شرحه و ماكان يتحدى الطالب\n\nالمياجر:\nكومن, كان اهوا الي يحطها كانت سهلة و بسيطة\n\nالفاينلات : كومن\n\nالقريد النهائي:\nA\nالصوت: واضح و غير ممل في الشرح\n\nإضافات :\nالدكتور ممتاز من جميع النواحي لاكن اتمنى يرتب له نوتات, لاتضيعه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522575-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/30", "user": "Guest", "ts": 1591128615000, "tid": 98557, "pn": 30}}, {"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - Term 201\n\nالتحضير : أكثر الدكاترة اللي كان متساهل في موضوع التحضير, كنت أشغل المحاضرة وأكمل رقود 👍 ولا عمره نادى بالأسماء ولا قد عمل تصويت مفاجئ 👍\nطريقة الشرح : شرحه ممتاز بس مشكلته يطولها وهي قصيرة, يعني عادي جدا يقعد 20د على أول سلايد يقعد يسولف عن الموضوع وطريقة الحل المسائل. بالنسبة لي ما كنت اتابع مقاطعه المسجلة الا في حل المسائل.\nالكويزات : الكويزات من سهلة الى متوسطة والآفرج دايم 21-19 من 30 وتصحيحه بطل.\nالميد: كومون\nالفاينلات :كومون\nالأورال: سهل, يتصل عليك فالتيمز ولازم تفتح الكام. طريقة الاختبار يجيبلك 4 صور مواضيعها عن اخر 4 دروس تقريبا. ولكن استعد انه ممكن تنتظر 5 ساعات لين يجي دورك. بدأ الأورال 7 المساء وخلص 1 الليل 👎\n\nالقريد النهائي: B+\n\nالصوت: أكسنت هندي بس واضح\nإضافات : طريقة المذاكرة كانت مقاطع Jeff Hanson + المسائل بسلايدات شمشاد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527100-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/32", "user": "Guest", "ts": 1608010784000, "tid": 98581, "pn": 32}}, {"id": "stk-dr-f98583", "n": "Dr. A. Al-Gadhib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce203 - 201\nالتحضير: ما يهتم فيه واعطى الكل ١٠ من ١٠ وهو كان يهددنا طول الترم\n\nالشرح: كان بداية الترم يشرح بالماوس على وايت بورد والشرح ملخبط ومو مفهوم وفي نص الترم حول على ايباد لكن شرحه برضوا عشوائي واحيانا يستخدم سلايدات شمشاد\n\nالكويزات: كانت سهلة واحيانا نفس حق الواجب او من السلايدات واحيانا يكون محدد سؤالين وواحد منهم بيجي ومرتين كانت Take home quiz\n\nالميد: كومن\n\nالفاينل: كومن\n\nالكلاس وورك عند الدكتور كان عالي جدا ممكن الافرج\n54 من 60\nوبسبب هذا الشيء صارت التوزيع استاندرد\nA+ 95\nA 90\nB+ 85\n\nالدكتور ما انصح فيه ابدا ولا عنده اوفيس اور ممكن طول الترم بس كان مسوي اوفيس اور مرتين او ثلاثة\n\nكنت احتاج اقل من 0.1 عشان اطلع قريد ولا دفني", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527616-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-a-al-gadhib/98583/19", "user": "Guest", "ts": 1609845107000, "tid": 98583, "pn": 19}}]}', 1591128615000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-ce203', 'stk-trad', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98557", "n": "Dr. Mohammad Saleh Al-Suwaiyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(CE203 Term 201 (Online\n\nالتحضير :\nماكان يسأل عن الحضور ولا ينادي بالاسماء ولكن اعتقد انه كان يحضر عن طريق النظر بالاسماء في البرنامج وممكن انه ماكان يحضر\n\nطريقة الشرح :\nيعطي مقدمة سريعة عن الدرس ويكون محضر له كم مثال متعلق بالدرس ويبدا يشرح عليه ويعدل عالسوال هو ويغير المطلوب في السوال بحيث يوضح جميع المفاهيم في الدرس\n\nالكويزات :\nالكويزات كانت سهلة جدا\n\nالمياجر:\nكومن, كان اهوا الي يحطها كانت سهلة و بسيطة\n\nالفاينلات : كومن\n\nالقريد النهائي:\n++A\nالصوت: واضح و غير ممل في الشرح\n\nإضافات :\nالدكتور اسطورة بما تعنيه الكلمة ماشاء الله عليه شرح واخلاق وكان متساعد ومتساهل جدا مع الطلاب. الدكتور ما يحب اللي يحضر ويقعد متفرج فقط كان يخلي الكل يشارك معه. الدكتور نوتاته ماكنت مفيدة يعني كانت مجرد امثله هو كان يشرح عليها واغلبها كانت عبارة عن صور وهو يحط السوال بنفسه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527553-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-saleh-al-suwaiyan/98557/32", "user": "Trad", "ts": 1609775319000, "tid": 98557, "pn": 32}}]}', 1609775319000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7794-ce203', 'stk-user7794', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98559", "n": "Dr. Hamdan Naser Al-Ghamedy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 203 132\nــــــــــــــــــــــــ\nالصراحه من أعظم المدرسين الي مرو علي بالجامعه …\nأنسان يعلمك أصل الكونسبت ويعلمك كيف تفكر …\nنظامي لأبعد درجة ممكن تتصورها …\n“نظام بريطانيين” …الأوفس أور حقة من الساعة 5-8 صباحاً\nكنت معاني معه بخصوص التحضير …من نص الترم وانا باقي لي غياب عالـdn\nأتمنى لو آخذ كورس ثاني معه … لكن للأسف الشديد … هالترم أخر ترم له أكاديمياً\n:::\nكل التوفيق 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1367915-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-hamdan-naser-al-ghamedy/98559/10", "user": "user7794", "ts": 1400633947000, "tid": 98559, "pn": 10}}]}', 1400633947000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2967-ce203', 'stk-user2967', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 203 - 093\n\nالتحضير : في بداية الكلاس\nطريقة الشرح : يكتب ع البورد بس ماتقتدر تكتب نوت وراه ابدااا لعدم وضوع مايكتبه\nوشرحه تعبااان جدا مايفهم\nالكويزات : نحلها بالبيت بس فيه تريك يحوس راسك 🙂\nوكل ترم تختلف طريقته للكويزات اترام يكون داخل الكلاس\nالمياجر: متوسطه\nالفاينلات : ^^^\nالقريد النهائي: مقبول 🙂\nالصوت: واضح س مشكلته سريع في الكلااام فماتفهم احيانا وش يقول\nإضافات : ان لقيت غيره يفضل ذلك\nوموفقين يارب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p744086-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/2", "user": "user2967", "ts": 1292339109000, "tid": 98562, "pn": 2}}]}', 1292339109000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4394-ce203', 'stk-user4394', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "فصل 111\n\nce203\n\nيعطيك نوتات هو كاتبها بيدها وخطه سئ سئ سئ\n\nوالله حرام على هل الاوراق الي تروح على الفاضي\n\nبس هو يقول الي يجمع الاوراق الي اعطيها لكم يوميا ويحطها في ملف اعطيه بونص\n\nشرحه في الاوفس رائع\n\nبس في الكلاس سئ\n\nالقريد النهائي: c", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p974325-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/6", "user": "user4394", "ts": 1327615088000, "tid": 98562, "pn": 6}}]}', 1327615088000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-i_bo_da7m-ce203', 'stk-i_bo_da7m', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الترم :\n102\n\nالمادة :\nCE 203\n\nالتحضير :\nيومياً … واحياناً قليل جداً ينسى … وينادي بالأسماء\n\nطريقة الشرح :\nكلام غير مفهوم , يوزع اوراق خط سيء جداً جداً لأبعد حد تحس البروبليم حلوه ودك تحلها 😁 بس الحل الي كاتبه يضيّق صدرك على هالخط المخيس 😞\n\nالكويزات :\nأذكر إنها تيك هوم … وصعببببه جداً جداً … ومرتين اتوقع كويز بالكلاس\n\nالمياجر والفاينلات :\nالمادة صعبة جداً … فلذلك اختباراتها صعبة , وبصراحة أصعب مادة مرّت علي بالجامعة\nتخصصي ME بس ضروري ناآخذها\n\nالقريد النهائي:\nF\n\nالصوت: عالي لكن كلام مو مفهوم , يمسك خط بالكلام ماتلحق تفهم له كلمة\n\nإضافات :\nالأخلاق زييييرووووو … سيء جداً جداً\nوسيء بالأوفيس آور\nوسيء بالتصحيح ( هو يصحح مسألة وحده لكل ميجر لكل طلاب المادة )\nابعد عنه قد ماتقدررررر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1161680-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/7", "user": "i_Bo_Da7m", "ts": 1357844418000, "tid": 98562, "pn": 7}}]}', 1357844418000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yoos-ce203', 'stk-yoos', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98562", "n": "Dr. Saeid Aboud Alghamdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - T 162\n\nالتحضير : كان عدد الطلاب في الكلاس تسعة بس فكان حافظهم ويحضر بالنظر غالبا\n\nطريقة الشرح : الشرح كان ملخبط و خطه سيء جدا … كان يعطينا هاند اوت مكتوبة بخط يده السيء فبالتالي ما تفهم منها شيء\n\nالكويزات :تقريبا اعطانا 5 كويزات وكلها كانت تيك هوم كويس بس مستحيل تجيب فيها 10/10\n\nالمياجر:كومن\n\nالفاينلات : كومن بس جابوا لنا من ماتيريال الميجر الاول والثاني\n\nالقريد النهائي:D\n\nالصوت: الصوت واضح\n\nإضافات : الواجبات كانت كثيرة 14 واجب تقريبا والتسليم كل اسبوع , الدكتور حريص جدا ان الطالب ما يتأخر في الحضور لكن دائما بعد المحاضرة ياخذ اقل شيء 5 دقائق ويرفض ان احد يطلع قبل يخلص كلامه لدرجة انه في يوم من الايام بدأت المحاضرة الي بعدها وهو ما طلعنا باقي !!!\n\nالدكتور غير مرن ابدا ودائما هو الصح وانت الغلط !\nعموما لا تنزل عنده ابدا ابدا واذا انحديت عليه وفيه مجال تأجل الماده أجلها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474338-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-saeid-aboud-alghamdi/98562/13", "user": "Yoos", "ts": 1496363251000, "tid": 98562, "pn": 13}}]}', 1496363251000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-banyan-ce203', 'stk-banyan', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203\nالتحضير\nيومياً ويكون في بداية المحاضرة اول 5 دقايق واذا قفل الباب ودخلت بعدهاا يحطك ليت\n\nالشرح\nاسلوبه رائع يكتب في السبورة ويشرح الكونسبت بسلاسة ويحل مسائل كثير وكافية واحيانا يوزع هنداوت فيهاا مسائل محلولة بخط يده ويشرحهاا\n\nالكويزات\nقليلة تقريبا 4 او 3 في السمستر وقصيرة جدا 10 دقايق وسهالاات اذا فهمت الكونسبت معااه لانها اسهل من الامثلة اللي يحلها معانا\n\nالصوت واللغة واضحة ولو في كلمة جديدة راح يشرحها\n\nمن افضل الدكاترة يشرح من قلب واسئلة المياجر ماتتجاوز الامثلة اللي يحلهاا مع ان الاختبارات كومن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p747120-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/5", "user": "Banyan", "ts": 1292763989000, "tid": 98578, "pn": 5}}]}', 1292763989000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-civil_engineer1-ce203', 'stk-civil_engineer1', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203\n\nالتحضير :في بداية الكلاس على طول وما يحب التأخر مرره\nطريقة الشرح : افضل مدرس مر علي بالشرح في الجامعة … المعلومة تدخل في راسك بالغصب … يتقبل الاسئلة حتى لوكانت غبية … والنوت حقه يغنيك عن الكتاب ويكفي للاختبار\nالكويزات :2 او 3 و تكون في يوم تسليم الهوموورك وبنفس ماتيريال الهوموورك ويكون في الغالب يطلب اول خطوتين من ايقزامبل في الكتاب\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: B\nالصوت: واضح جدا + لغة ممتازة مرة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p940884-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/8", "user": "civil_engineer1", "ts": 1322768270000, "tid": 98578, "pn": 8}}]}', 1322768270000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5216-ce203', 'stk-user5216', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بســــم الله\nسمستر 111 … CE203\n\nالتحضير : بعد 5 دقايق من بداية الكلاس وبعدها ليت … يعطيك فرصتين غياب بدون خصم وبعدها يخصم , يكرة التاخير ولا يحب تنشغل عنه خلال الشرح\n\nطريقة الشرح : مع اني كنت اجلس اخر شي وافهي ( لان كلاسه كان اخر كلاس عندي ) الا انه من افضل المدرسين الي مروا علي خلال دراستي الجامعية … فنااااااااان وكل شباب الكلاس يخشون معه جووو اذا بدا يشرح , انصح فيه بقوة للي يهتمون بالشرح\n\nالكويزات : عطانا 4 كوزات وبعد مااقنعناه الغى واحد واخذ افضل 3 ( مستواها متوسط ) واغلبها من امثلة الكتاب\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي للدكتور : يستاااااهل A+ وبقووووووه ولو فيه اعلى كان عطيته 😆\n\nالصوت: واضح وانجليزيته سليمه\n\nإضافات : بالنسبة للتجربتي معاه كنت منزل مع مدرس وغيروه وحطوه لي فكنت متشائم منه وفي بداية الفصل حسيته شديد وينشب للطلاب واجد ( من ناحية التاخير والهوموركات … يعطي الي ينقل من السلوشن 0 )\nلكن مع الوقت حسيت انه يدور على مصلحة الطالب وفعلا اجزم انه كل شعبتي في ذاك السمستر عندهم خلفيه ممتازة عن المادة بفضل الله ثم بجهودة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p970707-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/10", "user": "user5216", "ts": 1326928724000, "tid": 98578, "pn": 10}}]}', 1326928724000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_dulaziz-ce203', 'stk-a_dulaziz', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 203 -122\n\nالتحضير : يومي بأول الكلاس (شديد)\n\nطريقة الشرح : على السبورة أو هاند أوت يسلمها ويعرضها على البرجكتر\nالشرح رائع جدا أعتبره إلى الأن أفضل مدرس درسني بالجامعة يعرف كيف يوصل المعلومة\n\nالكويزات : من الهومورك\nالمياجر: المادة كومن و مياجره صعبة\nالصوت: واضح + سعودي أكيد اللهجة واضحة\n\nإضافات :\n\nالهموركات هو يختار الأسئلة بهاند أوت يعني ما في نقل من السلوشن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1220226-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/18", "user": "A_DULAZIZ", "ts": 1368010104000, "tid": 98578, "pn": 18}}]}', 1368010104000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8624-ce203', 'stk-user8624', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98578", "n": "Dr. Abdulrahman Khathlan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce203-132\n\nالتحضير : شديد جدا في التحضير ( يحضر أول دقيقتين إلى 5 دقائق أقصى شيء)\nطريقة الشرح : ممتاز جدا يشرح الأمثلة المهمة على السبورة ويوضح كل شيء بالتفصيل ويشرح بإخلااااااص\nالكويزات : سهلة جدا 3 كوزات تآخذ 10 دقايق\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :\nهذا الدكتور من النوادر … ما شفت دكتووور يشرح بضمير مثله ! يوزع أوراق فيها أمثلة محلولة ويهتم بالهومورك وما تروح للأوفس أور إلا تلقاه ملتزم بالمواعيد … وتصحيحه للمياجر جدا ممتاز\n\nدكتور ممتاز بمعنى الكلمة !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1377276-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdulrahman-khathlan/98578/20", "user": "user8624", "ts": 1401921314000, "tid": 98578, "pn": 20}}]}', 1401921314000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6719-ce203', 'stk-user6719', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أعرف واحد من الشباب أخذ عنه CE 203…يمدحه مرة في الشرح والأخلاق…\n(لاحظ أنا أقول في CE 203)…لأننا أخذنا معاه CE 303 وإنكرفنا كرف عمرنا ما شفناه…ولي عودة بخصوص هذا الكورس مع شمشاد…إن شاء الله\nوللعلم هذا الولد دافور مرة ومستواه first honor ما شاء الله…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p780039-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/5", "user": "user6719", "ts": 1296551228000, "tid": 98581, "pn": 5}}]}', 1296551228000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_3lol-ce203', 'stk-mr_3lol', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203\nالتحضير :يحضر كل كلاس وشديد بالتحضير\nطريقة الشرح : يشرح من السلايدات و شرحه مررررررررررره بطـــل\nالكويزات : سهله\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A+ ❤️\nالصوت: واضح والاكسنت فيها شوية هندي 😆\nإضافات :\nالدكتور تتعب وانت تقول بطــل ., 👍 👍\nطبعا طبيعة الماده كل اسبوع (هوم ورك) وهذي عند كل مدرس .,\nوبالعكس اشوفه انه متعااون , ودايم ما يأخر التسليم .,\nكل هالكلام على ماده CE 203 فقط", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p851436-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/9", "user": "MR_3LOL", "ts": 1307878302000, "tid": 98581, "pn": 9}}]}', 1307878302000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5938-ce203', 'stk-user5938', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce203-sem113\n\nالتحضير يوميا …\nوالصوت جيد …\nكل اسبوع كويز وهوم وورك (في الصيف ) …\nالكويزات سهله والتصحيح جيد …\nالمياجر كومن والفاينلات كومن …\n\nالرجال شرحه جيد ويحاول يوصل المعلومه للطالب …\nشرحه من سلايدات ممتازه جدا ومايمسك طبشور الا ما ندر …\n\nاذا ماحصلت عند الخثلان ولا الدليجان ممكن تنزل عنده …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1076908-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/15", "user": "user5938", "ts": 1344278592000, "tid": 98581, "pn": 15}}]}', 1344278592000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s_h_a_d_o_w-ce203', 'stk-s_h_a_d_o_w', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce203 - 113\n\nمن أفضل المدرسين الي درسوني في الجامعة… شرحه جدا ممتاز و يهتم بتوصيل المعلومة لجميع الطلاب بكافة مستوياتهم … حتى الاشياء الاساسية حقت ce201 كان يهتم بشرحها علشان يضمن انو الجميع يفهم.\n\nيهتم بالتحضير في آخر كل محاضرة و بسبب دا الشي في الغالب ما ينهي المحاضرة في وقتها\n\nكويزاته سهلة و يعطي هوموركات بشكل منتظم\n\nما يستخدم الويب سي تي بتاتا لكن يستخدم الايميل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1079828-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/16", "user": "S_H_A_D_O_W", "ts": 1345150849000, "tid": 98581, "pn": 16}}]}', 1345150849000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8288-ce203', 'stk-user8288', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ce203\nشررررررررررررررررررررررررررررررررررررررررررررررررررررررررررررررررريح\nويهتم بأسئلة الطلاب مهما كانت سخيفة\n\nيحب الطلاب اللي يسألونه كثير\n\nأنصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1290733-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/19", "user": "user8288", "ts": 1384904843000, "tid": 98581, "pn": 19}}]}', 1384904843000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-ce203', 'stk-abo_yazeed6', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ce203 ترم 132\n\nالدكتور شرحه ممتاز وهو فاهم المادة ,بصراحة مني فاهم ايش قصة الطلاب هنا اللي يتهمونه بالخبث.\n\nالدكتور طيب ويتجاوب مع أسئلتك ,مشكلته الوحيدة انه احيانا يقعد يشرح لك درس ويطول فيه اللي يخليه يتأخر عن باقي الماتيريال,فيقعد يشرح باقي الدروس بسرعة ,لكن مع هذا غالبا الدكتور يطول في الدروس الصعبة ,الأشياء الي يشرحها بسرعها غالبة تكون سهلة ويقدر حتى الطالب يذاكرها بنفسه.\n\nعنده هومورك كل أسبوع ,هوموركاته بعضها من الأولد الاقزامز وبعضها يجيبها من برى الكتاب, وهي مهمة جدا جدا جدا ,اذا حليتها بنفسك فاعتبر نفسك ضامن الميجر بإذن الله ,فادتنا كثير لمن ذاكرنا للفاينل ,لأنه ما في اولد فاينل ل ce203.\n\nتصحيح الدكتور بطل ,وهالشيء تقدر تتأكد منه لمن يجي يصحح سؤاله في الميجر ,راح تعرف أنه يعطيك أكثر من حقك.\n\nمجملا الدكتور ممتاز ,خله عندك كخيار ثاني لو فيه دكاترة أفضل منه,لكن لو ما بقى الا هو فتراه دكتور جيد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1367235-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/20", "user": "abo_yazeed6", "ts": 1400535443000, "tid": 98581, "pn": 20}}]}', 1400535443000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8901-ce203', 'stk-user8901', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده كورس ce 203 في الترم 133 (الصيف)\n\nالتحضير: يحضر أخر الكلاس لما يخلص اللكشر بمناداة أسماء الطلاب، ما يسجل تأخير، إذا تجي بعد الكلاس بربع ساعة أو ثلث ساعة ما عنده مشكلة، لكنه ما يفضلها تصير عادة بين الطلاب.\n\nالكوزات: سهلة إلى متوسطة، وتكون إسبوعية في يوم محدد يحدده نفسه، يرجع الكوزات مصححة في الإسبوع الي بعده.\n\nالهوموركات: متوسطة إلى صعبة، وتكون إسبوعية في يوم محدد يحدده نفسه، يرجع الهوموركات مصححة في الإسبوع الي بعده.\n\nالشرح: يستخدم سلايداته، الجميل أن سلايداته تحتوي على أسئلة كتاب وإختبارات قديمة وهي مهمة جدا ومفيدة في المذاكرة، ما يستخدم السبورة إلا نادرا\n\nالمياجر والفاينل: تصحيحه جدا ممتاز في المياجر، وأفرج مياجرنا كان مرتفع لعله بسبب التصحيح، إحنا أخذنا هذا الكورس بالصيف وكان هو الوحيد الي يدرسه لذلك هو من كان يحط لنا الأسئلة بالمياجر والفاينل وكانت في الغالب سهلة إلى متوسطة بسبب حر الصيف وشهر رمضان، بالنسبة للفاينل كان صعب بعض الشيء لعله كان يريد خفض الأفرج أو شيء من هذا القبيل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1390163-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/21", "user": "user8901", "ts": 1408183920000, "tid": 98581, "pn": 21}}]}', 1408183920000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8715-ce203', 'stk-user8715', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم ورحمه الله وبركاته\nce 203 (133\n\nالتحضير : يحضر نهاية كل كلاس ( ما يحسب تأخير ) بس لا تجي في نهاية الكلاس\nطريقة الشرح : شرحة سلايدات نادر يكتب على الصبورة بس شرحة جيد جدا الا حد ما يوضح الكونسبت ويعطي امثل حلوة وفيها افكار\nالكويزات : متوسطة الى سهلة (اسبوعيا )\nالقريد النهائي:b\nالصوت:واضح\nإضافات :\nالدكتور ينفع اذا انت بتشد وتهتم واذا بتهمل بتروح عليك لان المادة يبغالها متابعة اول باول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1390170-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/22", "user": "user8715", "ts": 1408186525000, "tid": 98581, "pn": 22}}]}', 1408186525000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdelaziz-ce203', 'stk-abdelaziz', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - TERM 153\n\nالتحضير :\nنهاية اللكتشر بالأسماء … مايحاسب على التأخير (ويقبل الميك أب)\nالله يهديه كان ما يحضر الا اذا خلص الكلاس يعني لازم تتأخر عن الكلاس الي بعده\n\nطريقة الشرح :\nشريييييييح درجة أولى مع مرتبة الشرف\nيشرح من السلايدات حقته ويكتب على السبورة اذا فيه شيء يحتاج توضيح\nالسلايدات حقته ممتازة فيها أفكار منوعة وتنفع للمذاكرة تبداً بأقزامبل سهل وبعدين تزيد صعوبتها\n\nالكويزات :\nسهلة إلى متوسطة\nأسبوعياً في يوم محدد ولا يمكن يتنازل عنها حتى أوقات المياجر وحتى آخر أسبوع\nفي الأخير أخذ أفضل 5 من 7 ( كان ترم صيفي )\n\nالمياجر:\nكان يحط أسئلتها هو مع محمد حسين ( مو متأكد )\nكان مستواها مقبول مو صعبة ولا بسهلة مررة\n\nالفاينلات :\nنفس الشيء ^^\nمستوى الأسئلة قريب من مستوى المياجر بس أصعب بشوي\n\nالقريد النهائي:\nB+\n\nالصوت:\nالأكسنت هندي يعني عادي نص الكلام يبلعه بس عادي بعد الأسبوع الاول تتعود عليه وتفهمه\nكلامه أحياناً يضحك ويقط كم كلمة عربي\n\nإضافات :\nالهوموركات حقته طويييييلة بس مهمة جداً وأسئلتها مقاربة لأسئلة المياجر\nانا ذاكرتها وذاكرت السلايدات حقته وطلعت بقريد حليو\nتسليم الهومورك أسبوعي ولا يمكن يتنازل عنه مثل نظام الكويزات يوم واحد يتفق مع الطلاب عليه\nبس خلاص يعني اذا الهومورك والكويز في نفس الأسبوع وغالباً يكونون على نفس الموضوع بمجرد أنك تحل الهومورك اعتبر نفسك جبت فل في الكويز بالراحة\n* القريدات نهاية الترم كاانت somehow disappointing", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457759-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/24", "user": "Abdelaziz", "ts": 1474083995000, "tid": 98581, "pn": 24}}]}', 1474083995000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.n.a-ce203', 'stk-m.n.a', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 -162\n\nالتحضير : نهاية الكلاس بلاسماء ما يدقق على التاخير بس الله يهديه ما يحضر الا بعد نهاية الكلاس يعني ممكن يبدا تحضير :55 و ياخرك على الكلاس اللي بعده ما عنده مشكلة\n\nطريقة الشرح : يشرح من سلايداته و ما يكتب على السبورة الا نادر و هذا شي ما حبيته. شرحه كمجمل جيد بس يضيع وقت باشياء تافهة و يخليك تمل من قبل ما يبدا\n\nالكويزات : متوسطة بس ما كان يعطينا وقت كافي , 7 كويرات اخذ احسن 5\n\nالمياجرو الفاينلات : نظام الكورس كل دكتور يصحح سؤاله فما يفرق\n\nالصوت: واضح جدا تسمعه من اول الممر , اكسنت هندي بس مفهوم\n\nإضافات : الدكتور حريص على مصحل الطالب\nواجباته كثييييير و من بره الكتاب موجودة بالريسورسس بس ارقام مختلفة انا اشوففها مفيدة لك يعني لو تذاكر من السلايدات بعدين تحل الواجب يكفيك للمبجر\nالدكتور اذا تكرف معه بتطلع بقريد حلو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474955-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/26", "user": "M.N.A", "ts": 1497217421000, "tid": 98581, "pn": 26}}]}', 1497217421000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_91110-ce203', 'stk-_91110', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203 - 163\n\nطريقة الشرح : يفتح سليدات خاصه فيهة, فيها شرح ومسائل حلوة مررة لاكن الدكتور خابص المادة ودرسها كثيير فأكثر الشرح يكون ارتجالي ثم يفتح المسائل في اخر السليدات ويحلها ( الصعبة يحلها على السبورة والسهلة يمشي عليها في السليدات )\n\nالكويزات : بالصيف ما مان فيه كوزات 👏\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: اكسنت همدي لاكن واضح وصوته عالي م شاء لله\n\nإضافات :\n\nايجابيات :\n- الدكتور درس المادة كثييييير ف يعرف كل شيء فيها ومواطن الأسئلة ينبه عليها والتركات الي دايم الطلاب يطيحون فيها ( نصيحة سجلها ترى بتستفيد كثيير ) .\n\n- حبيب وخفيف ظل ويمزح مع الطلاب ويستطرد في الكلاس .\n\n- متعاون جدا في المكتب واستفدت منه كثيير .\n\nالسلبيات :\n- من ناحيتي أنا اشوفها سلبية وغيري ممكن ما تهمه , لاكن الدكتور شمشاد يستطرد كثييير في أشياء تخص المادة وأشياء ما لها علاقة وهذا يشتت الطالب بعض الاحيان وومكن يقول شيء مهم وسط الإستطراد وانت مسررح ( الكلاس بالصيف مدته 70 دقيقة وكان ياخذه كامل م شاء الله عليه :muscle:) .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479578-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/27", "user": "_91110", "ts": 1504036735000, "tid": 98581, "pn": 27}}]}', 1504036735000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rami_ali_ce_1990-ce203', 'stk-rami_ali_ce_1990', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني CE 203 بالصيف وكان ال لاديفايزر تبعي بالكوأب(راح اعلق اخر شي عن ادائه بالادفايزرية معايا)\n\nالتحضير : CE 203 بالصيف اخر الكلاس\nطريقة الشرح : عنده سلايدات خاصة فيه اعتبرها مزبوطة تذاكر منها تجيب درجات حلوة\nالكويزات : كان متساهل فيها لاننا صيف وهوا الوحيد اللي يدرسها\nالمياجر: هوا يحط الاسئلة كاملة بالصيف كانت وسط اذا ذاكرت تبدع(كان في شباب عندهم اولد اكزام له مدري من فين جابوه ولاعطونا اياه)\nالفاينلات :كان يحط الاسئلة وتقدر تحل متوسطة … انصحكم تاخذون المادة دي CE 203 بالصيف لانها مو كومن …\nالقريد النهائي: يعطيك حقك\nالصوت: واضح\nإضافات : قصتي معاه بالصيف الحمدلله لطيفة وجميلة وامورنا عسل نجي للكوأب 😁 😁 😁 😁\nبداية الكوأب الدكتور سعيد وزعنا عالدكاترة وانتا وحظك … انا طلعلي شمشاد … للامانة احب طريقتو لانو واضح وصريح وتمشي معاه تمام يزبطك مايضيعك … الكوأب تبعي كان معا GE وكنا نعمل Project Management … الدكتور شمشاد انفجع وزعل مني واشتكاني للدكتور سعيد لكن بعدين اتسهلت الامور وزبطتلو الريبورت وساعدني الدكتور الاوسطا الله يجزاه خير في مسألة كدا خلتني اقلب الطاولة على الدكتور شمشاد … الحاصل الدكتور شمشاد كان متعاون لابعد درجة لاني وريته اني شغااال … وراجع الريبورت تبعي والحمدلله يوم البرزنتيشن تبعي كان يطالع فيا بنظرة افتخار قدام الدكاترة … بالعربي لازم تعرف تتعامل معاه وتشتغل وتتعب عشان يضبطك ومايقصر معاك لكن لا تنزلوا معاه ال CE 303 خذوها معا الدليجان نصييييييييييحة 👏 👏 👏 👏", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480778-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/28", "user": "Rami_Ali_CE_1990", "ts": 1506108266000, "tid": 98581, "pn": 28}}]}', 1506108266000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10843-ce203', 'stk-user10843', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98581", "n": "Dr. Shamshad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE203, Term:182\n\nالشرح: بداية، طريقته في الشرح سيئة جدا ولاتقدر تركز معاه، وباذكر الاسباب.\nاولا يفتح السلايدات ويسحب عليها ويبدا يشرح بالكلام فقط. لا يستخدم سبورة ولا يستخدم السلايدات ابدا، احيانا نص ساعة او اكثر تروح من المحاضرة وهو بس يتكلم بدون مايستخدم اي وسيلة ايضاح، طبعا خلال كلامه يطلع من موضوع ويدخل في خمسة مواضيع ثانية، وكلامه سريع، فغالبا بعد ١٠ دقايق تفقد التركيز معاه ولاعاد تقدر تربط بين المواضيع وتقعد تطالع الساعة تنتظر الوقت يخلص بس وتمشي 🙂\nنادرا مايحل مسألة عالسبورة، واذا بقى ١٠ دقايق راح للمسائل اللي في السلايدات ويقرأ الحل عالسريع، احيانا المسألة كاملة يشرحها فقط في نص دقيقة! وطبعا المحاضرة اللي بعدها مايرجع يكمل، يروح للدرس الجديد 🙂\n\nالتحضير: مايسمح ابدا بالتأخير. احيانا يحضر بعد نهاية الكلاس وياخذ ٥ دقايق زيادة 🙂 يعني عاد تتاخر عاللي بعده بس لا تتأخر عنده. مايسمح بالميك اب الا اذا اول مرة يمشيها لك.\nالكويزات: سهلة، ولكن لا تحاول تناقشه في تغيير موعد كويز، احد المرات خلص شرح الدرس وبنفس المحاضرة عطانا كويز عليه 🙂\n\nصراحة الدكتور يحب الطلاب جدا بنفس مقدار شدته عليهم، ولكن للاسف احيانا شدته تكون ضد مصلحة الطلاب ماهو صالحهم. باقي الدكاترة يأخرون موعد تسليم الواجبات مثلا اذا كان فيه اختبارات، لكن شمشاد مستحيل! فيضطرون الطلاب ينسخون الحلول وبكذا ماحد استفاد من الواجب والسبب عناد الدكتور.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507559-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shamshad-ahmad/98581/31", "user": "user10843", "ts": 1553081025000, "tid": 98581, "pn": 31}}]}', 1553081025000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8219-ce203', 'stk-user8219', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98583", "n": "Dr. A. Al-Gadhib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ce 203\nterm 141\n\nالدكتور يمزح ويسولف كثير مع الطلاب لدرجة مرة ما تحس بثقل الكلاس\nبداية كان يشرح مرة عـ السرييع (لما كانت المواضيع سهلة)\n\nبس لما يجي موضوع جاد،،، والله يا أخوان إنه من شرحه ومراجعة بسيييط قبل الاختبار حليت أصعب أسئلة الفاينل وأنا مغمض\nالدكتور فعلا كان متمكن من المادة\nولا يحسسك بثقلها\n\nالمواضيع إلي يركز (الصعبة) عليها يشمل فيها كل الأفكار ويحل أمثلة تكفيك تماما\nبس المواضيع السهلة يطقطق فيها 😆\nولو جيته الأوفيس عليها يرحب بيك ويشرح لك إلين تفهم\n\nالرجال جدا متمكن من المادة 👍\n\nيسوي قبل المياجر والفاينل هيلب سشنز… لا تفوتها\nبس أحضرهم وإنت مذاكر\n\nتقويمي النهائي: A++++\nمن أفضل الداكاترة والله،، ولو لقيته في أي كورس بيكون خياري الأول ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423209-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-a-al-gadhib/98583/17", "user": "user8219", "ts": 1438420091000, "tid": 98583, "pn": 17}}]}', 1438420091000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8890-ce203', 'stk-user8890', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98583", "n": "Dr. A. Al-Gadhib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Ce 203 - 142\n\nالمادة تحتاج أن الدكتور يغطي لك أكثر الأفكار الممكنة لأن أفكارها كثيرة …\nالدكتور علي الله يسامحه كان يجي كثير من الأحيان متأخر 17 دقيقة ويخلص الكلاس ما خلصنا مثال واحد، وانتهى السمستر وحنا ما خلصنا الماتيريال وحضرنا كلاسات بالليل.\nانصحك بدكاترة يطفشونك من كثر ما يحلون لك مسائل مثل د. الصويان.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1432397-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-a-al-gadhib/98583/18", "user": "user8890", "ts": 1446883186000, "tid": 98583, "pn": 18}}]}', 1446883186000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6144-ce203', 'stk-user6144', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f98589", "n": "Dr. Mesfer M. Al-Zahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "والله أخذت معه ce203 من فترة … يعني حوالي سنة أو سنة ونص ولكن لأن ما فيه أحد رد على الموضوع بأرد بالي أتذكره والطريقة “الي درست عنده عليها” …\n\nيعني لو هو تغير أو لو فيه معلومة ما أتذكرها لا تلوموني …\n\nوطالب دعواتكم 🙂\n\nالتحضير :\n\nالتحضير يومي يحضر هو بنفسه والأعذار لازم تكون أوفيشل “إلا لو كنت جيد وأقتنعته بعذر مقبول” …\n\nالتاخير مقبول عنده لحد معين … يعني تجي متأخر يحضرك بس يهزئكـ “بشكل ودي” وبكم كلمة عشان يحرجك وما تتأخر مرة ثانية …\n\nطريقة الشرح :\n\nالدكتور والشهادة لله شرييييح … يهتتتتم بفهم الطالب واستيعابه للمادة بشكل كبييير … ويزعل من الي يطنش المادة عنده …\nأنا أخذت في الـ201 قريد d وطلعت مو فاااهم شيء في الستاتيك … وأخذت معه في 203 قريد b رغم أني ما سلمت ولا هومورك ومذاكرتي للمادة بالاعتماد على شرحه في الكلاس …\n\nيشرح من سلايد ويستخدم السبورة للتوضيح … والدكتور فاااهم في المادة “203” (ومدرك أوومها) على قولة أهل الحجاز 🙂\n\nالكويزات :\n\nعنده حسب ما أذكر أربع كوزات تقريبا … وأظن أنه يأخذ أفضل ثلاث … كوزاته سهله وبيييسك وغالبا مستخلصة من أمثلة الكتاب …\nكنت أفهم معه في الكلاس ولا أذاكر إلا قبل المحاضرة بربع ساعة وأفرجي 7-9 من 10 …\n\nالمياجر:\n\nكووومن …\n\nالفاينلات :\n\nكووومن\n\nالقريد النهائي:\n\nأشوف الدكتور مميز غير كونه عميد شؤون الطلاب يخليه دايم مشغول عن طلابه ,\nبس الدكتور دايم محضر وفاهم ويوصل المعلومة بسهوووولة …\n\nوأشوفه يستاهل b - b+ …\n\nالصوت:\n\nصوته وااضح ومقبول بالنسبة لكلاسات مبنى 3 (الصغيرة) … وما أذكر أحد اشتكى من صوته أو من الأكسنت …\n\nإضافات :\n\nإذا أنت أنسان تركززز في الكلاس أنصصصحك فيه بقوووة وأنصحك تكون جالس قدام لأنه يهتم بالي قدامه أكثر من الي في أخر الكلاس …\n\nالحضور الحضور الحضور … يقددددر الطالب الي يحضر وما يغيب ولا يتأخر …\n\nآخيرا … لو سألني أحد عن أفضل دكتور للـce … بدون تردد الدكتور مسفر 🙂\n\nخلوق شريح متفهم ومتواضع …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1219173-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mesfer-m-al-zahrani/98589/14", "user": "user6144", "ts": 1367754143000, "tid": 98589, "pn": 14}}]}', 1367754143000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-suarez-ce203', 'stk-suarez', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f152669", "n": "Dr. Mohammed Al-Osta", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CE 203: 173\n\nالتحضير : دايم يحضّر و متساهل من ناحية التأخير. ( بعد اسبوعين من بداية الصيفي قال لنا انه حذف غيابين لكل طالب).\n\nطريقة الشرح : بداية الكلاس يشرح الكونسبت للدرس بعدها يفتح السلايدات ويحل لنا اكثر من مسألة بـ أفكار مختلفة. ( سلايداتها ممتازة)\n\nالكويزات : عطانا سبع كويزات وكانت سهلة وفي النهاية حذف اسوء كويزين.\n\nالقريد النهائي: A+\n\nالصوت: واضح ( اغلب كلامه عربي )\n\nإضافات : الدكتور محمد يعتبر من افضل الدكاتره اللي درسوني علماً واخلاقاً.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497892-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-mohammed-al-osta/152669/14", "user": "SUAREZ", "ts": 1534533620000, "tid": 152669, "pn": 14}}]}', 1534533620000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-ce203', 'stk-m_nd_m', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f176818", "n": "Dr. Faisal Mukhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T162 - CE203\n\nالتحضير :\nينادي الأسماء بعد مرور تقريبًا نصف الوقت… أحيانًا يحضر بكويز أو هومورك (سواء كان تسليم من الطلاب أو منه)… ما عنده مشكلة تتأخر إطلاقًا و مرن جدًا و حبيب\n\nطريقة الشرح :\nسلايدات و سبورة… يبدأ بشرح الكونسبت و القوانين ثم يبدأ يحل جميع الأسئلة على السبورة\n+السلايدات يرفعها على البلاكبورد أول بأول\n\nالكويزات :\nأسبوع اي و اسبوع لا و سهلة و 90% تجي نسخ لصق من الهومورك لأنه هو يقولنا ترا بتجي من الهومورك الفلاني أو الفلاني… حرام تضيع الكلاسورك عنده\n\nبالنسبة للهوموركات… فأغلبها تجي من برا الكتاب و بعض المرات صعب تلاقي السليوشن (إذا حاب تتأكد من أجوبتك أو تنسخ) و تقريبًا كان عندنا هومورك أسبوعيًا و كان يتعاون معنا بموعد التسليم في أكثر من مرة\n\nبالنسبة لتصحيحه فمجرد أنك حليت حتى إذا كله كله خطأ يعطيك أقل شي 5 من 10… و إذا حلك صحيح بس غلط بشغلة بسيطة ممكن يمشيها لك تاخذ 10 أول ممكن ينقصك علامة و لا اثنين\n\nالمياجر: بمواد السيفيل كل دكتور يصحح سؤاله و تصحيحه كان ممتاز حتى لطلاب الشعب الثانية\n\nكان يسوي لنا Help session قبل المياجر\n\nالفاينلات : للأسف ما أعطانا فرصة نراجع الفاينل على طول القريد بالبورتال… و هذه عادة عند كل دكاترة القسم للأسف برضو\n\nالقريد النهائي: أفرج سكاشن الكورس هذا… أما بالنسبة لقريد النهائي للدكتور فأتركه لكم\n\nالصوت: واضح جدًا جدًا\n\nإضافات :\n\nالزبدة…\n\nمحترم و حبيب و خدوم جدًا بالساعات المكتبية\nتصحيحه كويس\nمتعاون بمواعيد الكويزات و تسليم الواجبات\nشرحه جيد\nمتعاون بالتحضير\nيتواصل مع الطلاب على الإيميل\n\nالهوموركات كثيرة أسبوعيًا (مشتركة بين الدكاترة تقريبًا)\nبعض المرات يعطي وقت قصير للكويز\n\nملف شامل فيه سلايداته هوموركاته و السيلابس:\nCE203 - STKFUPM&RESOURCES | تحميل\n\nتجدونها أيضًا بالريسورسيز و لمعلومات آخرى عن الكورس تجدونها بموضوع تقييم الكورس (سأضيف تقييمي لاحقًا)\n\nإن شاء الله ما أكون نسيت شي 😅", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474708-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/faisal-mukhtar/176818/3", "user": "M_nd_m", "ts": 1496860069000, "tid": 176818, "pn": 3}}]}', 1496860069000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh1417_2015-ce203', 'stk-saleh1417_2015', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f178250", "n": "Dr. Saheed Adekunle", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله راح ابتدي بنفسي بتقييم الدكتور:\n\nCE203-171\n\nالتحضير :\nيحضر البلاكبورد بنص المحاضرة ويحاسب المتأخرين\n\nطريقة الشرح :\nيشرح من سلايدات ويستعمل السبورة لتوضيح فكرة او رسم FBD لكن الرجال للأمانة فاهم الكونسبت ومتجرعه بعد وحمااااااااسي جدا في الكلاس عادي كذا تحصله عند شاشة الكمبيوتر فجأة بأقل من ثانية تلقاه عند البورد بيوضح لك ترك او فكرة وينكت احيانا نكت لتغيير الجو بس لاتحرص تسمعهم :sneezing_face:.\n\nالكويزات :\nاخذنا تقريبا ١٠ كويزات وحذف اسوأ ٣ لكن تصحيحه غريب نوعا عادي تحل وتتعب وتشتغل اخر شي يعطيك ٦/١٠ :ninja: والعكس ايضا تحس انك جايب ام العيد فجأة تصير اخذ ٥/١٠ .\n\nالمياجر:\nكومن ، لكن راح اتكلم عن تصحيحه للسؤال اللي ماسكه يهتم بخطواتك ،طريقة حلك والوحدات بغض النظر عن الارقام .\n\nالفاينلات :\nكومن\n\nالصوت:\nالاكسنت افريقي بس مسموع وجهوري جداا للأمانه راح تواجه صعوبة فيه بالبداية فقط وبعدها راح تتعود\n\nالقريد النهائي:\nتقيمي للدكتور B+\n\nإضافات :\nالدكتور مخلص جدا في شرحه ومتفاني ويحاول يوصل المعلومة بشتى الطرق ويراعي ظروف الطلاب لتأجيل كويز او هوم ورك وغير كذا يرحب فيك في الاوفيس ويقول خذ رقمي وتواصل معي واتسب اذا عندك سوال او ودك تقابلن بموعد اذا مايناسبك ساعاتي المكتبية ،، بالنهاية لم انددم انه طلع لي رغم اني سجلته TBA\nالله يوفقه وين ماراح فعلا يخاف الله في طلابه 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485475-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saheed-adekunle/178250/2", "user": "Saleh1417_2015", "ts": 1515010646000, "tid": 178250, "pn": 2}}]}', 1515010646000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11978-ce203', 'stk-user11978', 'CE 203', 'doc', '{"docs": [{"id": "stk-dr-f178250", "n": "Dr. Saheed Adekunle", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nفصل 203\nCE203\nالتحضير : تلقائي، ما يعلن عن الغيابات في الكلاس\n\nطريقة الشرح : يكتب على الشرائح لكن غالبًا يفتح صفحة فاضية. يشرح الكونسبت بالتفصيل أول بعدين يدخل على طرق الحل.\n\nالكويزات : خيارات، ما كنت اشوفها صعبة لكن أحيانًا يجيب افكار جديدة\n\nالميد والفاينال: كومن وخيارات\n\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : أعتبره من أفضل الدكاترة اللي درسوني لأنه يشرح لك عشان تفهم كمهندس وهذا الشيء مهم لان الدروس تعتبر من اساسيات الهندسة، ويسهل لك المادة عن طريق اختصاراته وتعاونه.\n\nباختصار، ذا الدكتور هو البلاك بانتر الحقيقي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531294-ce203", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saheed-adekunle/178250/6", "user": "user11978", "ts": 1629137418000, "tid": 178250, "pn": 6}}]}', 1629137418000, 1794826837, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
